type Coupon = { code: string; percentOff: number; expiresOn: string };
type Cart = { lines: { sku: string; quantity: number; unitPriceCents: number }[] };
type PricedCart = Cart & { totalCents: number };

const COUPONS: Coupon[] = [
  { code: 'WELCOME10', percentOff: 10, expiresOn: '2099-12-31' },
  { code: 'SPRING15', percentOff: 15, expiresOn: '2025-05-31' },
];
const STOCK: Record<string, number> = { 'TENT-2P': 4, 'MUG-SET': 0 };

type Result<T, E> = { ok: true; value: T } | { ok: false; error: E };
const ok = <T>(value: T): { ok: true; value: T } => ({ ok: true, value });
const err = <E>(error: E): { ok: false; error: E } => ({ ok: false, error });

type CouponError =
  | { type: 'coupon-unknown'; code: string }
  | { type: 'coupon-expired'; code: string; expiredOn: string };
type StockError = { type: 'out-of-stock'; sku: string; available: number };
type CheckoutError = CouponError | StockError;

function findCoupon(code: string, today: string): Result<Coupon, CouponError> {
  const coupon = COUPONS.find((c) => c.code === code);
  if (!coupon) return err({ type: 'coupon-unknown', code });
  if (coupon.expiresOn < today) return err({ type: 'coupon-expired', code, expiredOn: coupon.expiresOn });
  return ok(coupon);
}

function checkStock(cart: Cart): Result<Cart, StockError> {
  for (const line of cart.lines) {
    const available = STOCK[line.sku] ?? 0;
    if (available < line.quantity) return { ok: false, error: { type: 'out-of-stock', sku: line.sku, available } };
  }
  return { ok: true, value: cart };
}

function checkout(cart: Cart, couponCode: string | null, today: string): Result<PricedCart, CheckoutError> {
  const stocked = checkStock(cart);
  if (!stocked.ok) return stocked;

  const subtotal = cart.lines.reduce((sum, l) => sum + l.quantity * l.unitPriceCents, 0);
  if (couponCode === null) return ok({ ...cart, totalCents: subtotal });

  const coupon = findCoupon(couponCode, today);
  if (!coupon.ok) return coupon;
  return ok({ ...cart, totalCents: Math.round(subtotal * (1 - coupon.value.percentOff / 100)) });
}

function errorMessage(e: CheckoutError): string {
  switch (e.type) {
    case 'coupon-unknown': return `We don't recognise the code ${e.code}.`;
    case 'coupon-expired': return `${e.code} expired on ${e.expiredOn}.`;
    case 'out-of-stock': return `Only ${e.available} of ${e.sku} left in stock.`;
  }
}

// ---- Type tests (do not edit) ----
type T1 = Expect<Equal<ReturnType<typeof findCoupon>, Result<Coupon, CouponError>>>;
type T2 = Expect<Equal<ReturnType<typeof checkout>, Result<PricedCart, CheckoutError>>>;

function typeTests(r: Result<Coupon, CouponError>) {
  // @ts-expect-error: value is only available after checking ok
  r.value.code;
  if (r.ok) r.value.code;
}

const cart: Cart = { lines: [{ sku: 'TENT-2P', quantity: 1, unitPriceCents: 18900 }] };
const outcome = checkout(cart, 'SPRING15', '2026-10-05');
console.log(outcome.ok ? outcome.value.totalCents : errorMessage(outcome.error));
